      "content": "// Generated by scripts/sync-shared.mjs from shared/host/pair-access.ts. Do not edit this copy; edit the shared source and run \"node scripts/sync-shared.mjs\".\n/**\n * Pairing trust fence shared by plugins that expose host routes: loopback\n * (the desktop) always passes; a live paired-device cookie is an additional\n * allow path when remote-web-ui is loaded. The consuming plugin never\n * depends on that plugin — without the service the fence stays\n * loopback-only.\n *\n * Per-package wrappers (access.ts) call this with their own name so each\n * plugin keeps a self-describing export; the security decision lives only\n * here.\n */\nimport type { IncomingMessage } from 'node:http'\nimport { isLoopbackRequest } from './loopback.ts'\n\n/** Structural pairing lookup (no package dependency on remote-web-ui). */\ninterface PairingAccess {\n  isPairedDevice(request: IncomingMessage): boolean\n}\n\n/**\n * Structural host-context shape: shared sources carry no @deepseek-ai\n * dependency (the shared package must typecheck standalone), so the fence\n * reads only the two members it needs; cordis Context satisfies this.\n * ctx.get is optional on the test harness; production Context always has it.\n */\ninterface LookupCtx {\n  get?(name: string, strict?: boolean): unknown\n  remoteWebUiPairing?: PairingAccess\n}\n\n/**\n * Whether this request may enter the plugin's host routes.\n * @param ctx - host context; may expose remoteWebUiPairing.\n * @param request - the incoming HTTP request.\n * @returns true for loopback, or a live paired-device cookie.\n */\nexport function isPairedOrLoopbackAllowed(ctx: LookupCtx, request: IncomingMessage): boolean {\n  if (isLoopbackRequest(request)) return true\n  return lookupPairing(ctx)?.isPairedDevice(request) === true\n}\n\n/**\n * The pairing service, or undefined when this composition does not expose it.\n *\n * Two lookups exist because the fence is shared with test harnesses that hand\n * over a bare object: a real cordis context resolves services through `get`, a\n * harness may carry the property directly. `get(name, false)` is the\n * non-strict form, so an unloaded service answers undefined rather than\n * throwing. Reading an un-injected service as a PROPERTY throws instead\n * (`cannot get property \"remoteWebUiPairing\" without inject`); a trust fence\n * must answer \"not paired\" in that case, never leak the error into the route\n * handler, where the host web server turns it into an empty-body 400 (#1942).\n */\nfunction lookupPairing(ctx: LookupCtx): PairingAccess | undefined {\n  if (typeof ctx.get === 'function') {\n    const viaGet = ctx.get('remoteWebUiPairing', false)\n    return isPairingAccess(viaGet) ? viaGet : undefined\n  }\n  try {\n    const viaProperty = ctx.remoteWebUiPairing\n    return isPairingAccess(viaProperty) ? viaProperty : undefined\n  } catch {\n    return undefined\n  }\n}\n\nfunction isPairingAccess(value: unknown): value is PairingAccess {\n  return value !== undefined\n    && value !== null\n    && typeof (value as PairingAccess).isPairedDevice === 'function'\n}\n"
